/** Compares the complete API reference tree, including removed and newly added pages. */
import { readFileSync, readdirSync } from 'node:fs';
import { join, relative } from 'node:path';

/** Indexes files only; empty directories do not form part of the published API reference. */
function referenceFiles(root) {
  return new Set(
    readdirSync(root, { recursive: true, withFileTypes: true })
      .filter((entry) => entry.isFile())
      .map((entry) => relative(root, join(entry.parentPath, entry.name))),
  );
}

/** Reports relative paths whose generated bytes differ from the committed reference. */
export function compareApiDocs(committed, generated) {
  const expected = referenceFiles(committed);
  const actual = referenceFiles(generated);
  return [...new Set([...expected, ...actual])].sort().filter((path) => {
    if (!expected.has(path) || !actual.has(path)) return true;
    return !readFileSync(join(committed, path)).equals(readFileSync(join(generated, path)));
  });
}
